css:
body :where([data-bz-node="vp"]) .bz-block{padding:0}
body :where([data-bz-node="vp"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="vp"]>.bz-container{padding-inline:0}

body [data-bz-node="vp"]{background:#fff;padding:90px 0}
body [data-bz-node="vp"]>.bz-container{max-width:var(--container)}
body [data-bz-node="vp-h"] h2{font:700 36px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="vp-intro"] .bz-text{margin-top:22px}
body [data-bz-node="vp-intro"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0}
body [data-bz-node="vp-grid"]{margin-top:34px}
body [data-bz-node="vp-grid"]{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,250px),1fr));gap:24px;align-items:stretch}

body [data-bz-node^="vp-card-"]{grid-column:auto;display:flex;flex-direction:column;background:#fff;border:1px solid #d4d4d2;padding:32px 30px 34px;box-sizing:border-box}
body [data-bz-node^="vp-title-"] h3{font:700 22px/1.15 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0 0 18px}
body [data-bz-node^="vp-para-"]{display:block;margin-bottom:14px}
body [data-bz-node^="vp-para-"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;margin:0}
body [data-bz-node^="vp-cta-"]{margin-top:auto;padding-top:10px}
body [data-bz-node^="vp-cta-"] .bz-btns{margin:0}
body [data-bz-node^="vp-cta-"] .bz-btn{display:inline-flex;align-items:center;justify-content:center;height:44px;padding:0 24px;border:0;border-radius:2px;background:var(--accent);color:#fff;font:700 11px/1 var(--font-body);letter-spacing:.18em;text-transform:uppercase;text-decoration:none}
body [data-bz-node^="vp-cta-"] .bz-btn:hover{background:var(--accent-dark)}

body [data-bz-node="vp-grid"]>.bz-col{grid-column:auto}
body [data-bz-node="vp-ahead-h"] h2{font:700 26px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:56px 0 0}
body [data-bz-node="vp-ahead"] .bz-text{margin-top:18px}
body [data-bz-node="vp-ahead"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0}
@media (max-width:1100px){body [data-bz-node="vp"]{padding:64px 24px}body [data-bz-node="vp-h"] h2{font-size:30px}}
@media (max-width:640px){body [data-bz-node="vp"]{padding:48px 20px}body [data-bz-node="vp-h"] h2{font-size:26px}body [data-bz-node="vp-ahead-h"] h2{font-size:22px;margin-top:40px}body [data-bz-node^="vp-card-"]{padding:24px 20px 26px}body [data-bz-node^="vp-title-"] h3{font-size:19px}}
